from pytimeparse2 import parse

items = [
    "2h32m",
    "1 week, 2 days 3hrs, 4minute 5s",
    "7:02.223",
    "2 days,  4:13:02",
    "3 days, 4 hours",
]
values = []
for item in items:
    if item.count(":") == 1:
        values.append(parse(item, granularity="minutes"))
    else:
        values.append(parse(item))

bucket = {"large": [], "small": []}
for value in values:
    if value > 100000:
        bucket["large"].append(value)
    else:
        bucket["small"].append(value)

print(values)
print(bucket)
print(sum(bucket["small"]))
